/// <reference types="vite/client" />

/** App version from apps/web/package.json (injected by vite.config.ts). */
declare const __LEXVM_VERSION__: string;
/** True in the single-file offline build (`vite build --mode singlefile`). */
declare const __LEXVM_SINGLEFILE__: boolean;

/**
 * Built-in packs inlined into the single-file build (generated by vite.config.ts
 * from public/packs). `null` in the normal build, where packs are fetched.
 */
declare module "virtual:lexvm-builtin-packs" {
  export const bundled: null | {
    /** Parsed packs/index.json. */
    catalog: unknown;
    /** Parsed pack files keyed by their catalog `file` path. */
    packs: Record<string, unknown>;
  };
}
